// ── Validate Approval Webhook Input ──
const body = $input.first().json.body;

if (!body.session_id) {
  throw new Error('Missing required field: session_id');
}

const validDecisions = ['approve', 'modify', 'reject'];
const decision = (body.decision || '').toLowerCase();

if (!validDecisions.includes(decision)) {
  throw new Error(`Invalid decision "${decision}". Must be one of: ${validDecisions.join(', ')}`);
}

return [{
  json: {
    session_id: body.session_id,
    decision: decision,
    filePath: `./canvas-state/${body.session_id}.json`
  }
}];

const fs = require('fs');

const sessionId = $('Validate Input').first().json.session_id;
const filePath = `/canvas-state/${sessionId}.json`;

if (!fs.existsSync(filePath)) {
  throw new Error(`Session file not found: ${filePath}`);
}

const raw = fs.readFileSync(filePath, 'utf8');
const sessionState = JSON.parse(raw);

return [{ json: sessionState }];

// ── Process Approval Decision ──
const sessionState = $input.first().json;
const decision = $('Validate Input').first().json.decision;
const sessionId = $('Validate Input').first().json.session_id;

let updatedState = { ...sessionState };
let response;

switch (decision) {
  case 'approve':
    updatedState.status = 'running';
    updatedState.approved_at = new Date().toISOString();
    response = {
      session_id: sessionId,
      status: 'approved',
      next: 'agents_dispatched',
      goal: sessionState.goal,
      tasks: sessionState.tasks,
      message: `Session ${sessionId} approved. ${sessionState.tasks.length} agent(s) will be dispatched.`
    };
    break;

  case 'reject':
    updatedState.status = 'rejected';
    updatedState.rejected_at = new Date().toISOString();
    response = {
      session_id: sessionId,
      status: 'rejected',
      message: `Session ${sessionId} has been rejected.`
    };
    break;

  case 'modify':
    updatedState.status = 'modification_requested';
    updatedState.modified_at = new Date().toISOString();
    response = {
      session_id: sessionId,
      status: 'modification_requested',
      message: `Session ${sessionId} requires modification. Please re-submit with adjusted brief.`
    };
    break;
}

return [{
  json: {
    ...response,
    updatedState: updatedState
  }
}];

const fs = require('fs');
const path = require('path');

const data = $input.first().json;
const dir = '/canvas-state';
const filePath = path.join(dir, `${data.updatedState.session_id}.json`);

// Create directory if it doesn't exist
if (!fs.existsSync(dir)) {
  fs.mkdirSync(dir, { recursive: true });
}

fs.writeFileSync(filePath, JSON.stringify(data.updatedState, null, 2), 'utf8');

return [{ json: { ...data, state_updated: true, file_path: filePath } }];
